        	"Choose relational model",
			"choose model",
			QUESTIONMESSAGE,
			null, 
			rmodels,rmodel);
	}
	return antwort
}
function nvl(x){return x==null ? "" : x }

function writeMapLine(fw,tab,enti,col,attr){
	//message('write'+tab+enti+col+attr)
	fw.write(nvl(enti)+';'+nvl(attr)+';'+tab+';'+nvl(col)+'\n')
}
function printColsMap(fw,tab){
	cols = tab.getElementsCollection().toArray()
	writtenCols = {}
	for (icpcm=0;icpcm < cols.length;icpcm++){
		col = cols[icpcm]
		colkey = tab+'.'+col

//		//FK mapped to Relations
//		if (col.isFKColumn()) {
//			fks = col.getAllFKs()
//			for (ifk=0;ifk<fks.length;ifk++){
//				fkID=fks[ifk].getObjectID()
//				fkmaps = getContainerMaps(fkID)
////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ifk+' :1: '+fkID+' : '+fkmaps.length)
//				for (ir=0;ir<fkmaps.length;ir++){
//					rela = relationSet.getObjectByID(fkmaps[ir].logID)
////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ir+' :2: '+fkmaps[ir].logID+':'+rela)
//					if (rela == null) rela = inheritanceSet.getObjectByID(fkmaps[ir].logID)	
////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ir+' :3: '+rela)
//					writeMapLine(fw,tab,rela,col, null)
//					writtenCols[colkey]=true
//				}
//			}
//		}

		colmaps=getColMaps(col.getObjectID())
		if (colmaps.length>0) {
			// Column ist gemapped
			for (impcm=0;impcm<colmaps.length;impcm++){
				curmap = colmaps[impcm]
				parent = containerMappings[curmap.parentID] 
				switch (parent.logType){
				 case ENTITYPE: 
				 	logElem = entitySet.getObjectByID(parent.logID)
					attrName=logElem.getElementByID(curmap.logID).getName()
					break;
				 case RELATYPE:
					logElem=relationSet.getObjectByID(parent.logID)
					attrName = getRelationAttrByID(logElem.getAttributesCollection(),curmap.logID).getName()
					break;
				 case INHERITTYPE:
					logElem=inheritanceSet().getObjectByID(parent.logID)
					attrName = '???'
					break;
				 default:
					logElem='???'
					attrName = parent.relType
					//throw new Error("\n  Column'"+colkey +" unknown logical mapping type: "+parent.logType);
				}
				writeMapLine(fw,tab,logElem.getName(),col, attrName)
				writtenCols[colkey]=true
			}
		}
		//Jede Column wird mind. 1x geschrieben.
		if (!writtenCols[colkey]) writeMapLine(fw,tab,null,col,null)
	}
}
function printCols(fw,tab){
	maps = getContainerMaps(tab.getObjectID())
	if (maps.length==0) {
		printColsMap(fw,tab)
	} else {
		//print entity/relation - Mapping of Table
		for (impc=0;impc<maps.length;impc++){		
			switch (maps[impc].logType) {
			 case ENTITYPE: 
				enti = entitySet.getObjectByID(maps[impc].logID)
				if (enti != null) writeMapLine(fw,tab,enti.getName(),null,null)
				break;
			 case RELATYPE:
				rela=relationSet.getObjectByID(maps[impc].logID)
				if (rela != null) writeMapLine(fw,tab,rela.getName(),null,null)
				break;
			 case INHERITTYPE:
//				inher=inheritanceSet().getObjectByID(maps[impc].logID)
//				if (inher != null) writeMapLine(fw,tab,inher,null,null)
				break;
		  	 default:
				throw new Error("\n  Table'"+tab
				   +" unknown logical mapping type: "+maps[impc].logType);
			}
		}
		printColsMap(fw,tab)
	}
}


function chooseFile(direc,fileName){
	//Create a file chooser
	var Filebrowse = Java.type("javax.swing.JFileChooser");
	var File = Java.type("java.io.File");
	f = new Filebrowse(direc);
	f.setSelectedFile(new File(fileName));
	returnVal= f.showSaveDialog(null);
	if (returnVal == Filebrowse.APPROVE_OPTION) {
		return  f.getSelectedFile();
	} else {
		return null
	}
}
function createFile(fileName){
	//Create a file chooser
	var FileWriter=Java.type('java.io.FileWriter')
	fw = new FileWriter(fileName);    
	return fw
}

function headers(rmodels,nurX){
	retval = ''
	for (ih=0;ih<rmodels.length;ih++){
		retval += ';'+rmodels[ih]
		// extra header for table | attribute entries
		if (! nurX) { retval += ';column;ID'}
	}
	return retval
}

function getColName(rmod,tabID,colID){
	tab=rmod.getTableSet().getObjectByID(tabID)
	col = tab.getElementByID(colID)
	return tab+'.'+col
}

function colProperty(curmodel,tabname,colname,propName){
	table = curmodel.getTableSet().getByName(tabName);
	if (table == null) return ""
	column = table.getElementByName(colName);
	extID= column.getProperty(propName)
	return ((extID == null) || (extID == ".")) ? "" : extID
}

function findFK(fks,fkID){
	for (iloc in fks) {
//		if (fkID == "8AEA1CA4-3B90-4F1D-37AE-8A0FD50F8996") {message(fks[iloc].getTable()+fks[iloc].getObjectID()+fks[iloc])}
		if (fks[iloc].getObjectID() == fkID) return fks[iloc]
	}
	return null
}
function tabList (maps,elemType,curmodel) {
	if (maps == null) return ''
	retval = ''
	if (elemType != 'Entity') {
		fks = curmodel.getFKIndexAssociationSet().toArray()
	}
	for (i in maps) {
		retval += (retval == '') ? '' : EXCELSEPARATOR 
		if (elemType == 'Entity') {
			tabName = maps[i].tableName 
		} else {			
			fk = findFK(fks,maps[i].relID)
			if (fk != null) {
				tabName = fk.getTable()
			} else {
				tabName = maps[i].tableName // falls es m:n ist ist es eine Table
			}
		}
		retval += tabName
	}
	return retval
}

function elements(rmodels,logID,elemType,nurX){
	retval = ''
	for (ih=0;ih<rmodels.length;ih++){
		curmodel = rmodels[ih]
		retval += ';'
		maps = getLogMap(logID,curmodel)
		if (maps.length > 0) {
			retval += nurX ? 'X': tabList(maps,elemType,curmodel)
		}
		// Extra columns are empty
		retval += nurX ? '' : ';;'
	}
	return retval
}

function attrElements(rmodels,attrID,nurX) {
	retval = ''
	for (irmpm=0;irmpm<rmodels.length;irmpm++){
		curmodel = rmodels[irmpm]
		attrmaps = getAttrMap(attrID,curmodel.getName())
		//message(curmodel.getName()+':'+attrID+':'+attrmaps.length)
		if (attrmaps.length > 0) {
			if (nurX) { x = ';X' 
			} else {
				x = ''
				tabNames = ''
				colNames = ''
				colIDs = ''
				for (key in attrmaps){
					attrmap = attrmaps[key]
					tabName= containerMappings[attrmap.parentID].tableName
					colName = curmodel.getTableSet().getByName(tabName).getElementByID(attrmap.relID)
					tabNames += tabName + EXCELSEPARATOR
					colNames += colName + EXCELSEPARATOR
					colIDs += colProperty(curmodel,tabName,colName,EXTIDPROPNAME) + EXCELSEPARATOR
				}
				tabNames = tabNames.slice(0,-1)
				colNames = colNames.slice(0,-1)
				colIDs = colIDs.slice(0,-1)
				x +=  ';' + tabNames + ';' + colNames + ';' + colIDs  
			}
		} else {x = nurX ? ';' : ';;;'}
		retval += x
	}
	return retval
}

function logicalElement(rmodels,logElem,nurX){	
	elemID = logElem.getObjectID()
	attrs = null
	if (logElem.getObjectTypeName() == 'Entity'){
		line= logElem.getName()+';'
		line += elements(rmodels,logElem.getObjectID(),logElem.getObjectTypeName(),nurX)
		line += '\n'
		fw.write(line)
		attrs=logElem.getElementsCollection().toArray()
	} else if (logElem.getObjectTypeName() == 'Relation') {
		if (logElem.isManyToMany()) { // FK-Mapping ist nicht trivial bei seltsamen Modellen
			line= logElem.getName()+';'
			line += elements(rmodels,logElem.getObjectID(),logElem.getObjectTypeName(),nurX)
			line += '\n'
			fw.write(line)
			attrs=logElem.getAttributesCollection().toArray()	
		} 
	} else { // assume inheritance
		// Inheritance sind schon entities line += elements(rmodels,logElem.getObjectID(),logElem.getObjectTypeName(),nurX)
		// Inheritance becomes fk-columns
	}
 	if (attrs != null){
		for (iattrac=0;iattrac<attrs.length;iattrac++){
			attr = attrs[iattrac]
			attrID = attr.getObjectID()
			key=elemID+'.'+attrID

			line= logElem.getName()+';'+attr.getName()
			line += attrElements(rmodels,attrID,nurX)
			line += '\n'
			fw.write(line)
		}
	}
}
function printElementGroup(rmodels,group,nurX){	
	if (group != null) {
		for (ig=0;ig < group.length;ig++) {
			logicalElement(rmodels,group[ig],nurX)
		}
	}
}

function printMatrix(fw,nurX) {
	logicalModel = model.getDesign().getLogicalDesign();
	entitySet = logicalModel.getEntitySet()
	relationSet = logicalModel.getRelationSet()
	inheritanceSet = logicalModel.getInheritanceRelationSet()
	rmodels = model.getDesign().getRelationalDesigns().toArray();
	getAllMappings(rmodels)
	fw.write('entity;attr'+headers(rmodels,nurX)+'\n')
	printElementGroup(rmodels,entitySet.toArray(),nurX)
	printElementGroup(rmodels,relationSet.toArray(),nurX)
	// sind schon entities   
	// printElementGroup(rmodels,inheritanceSet.toArray(),nurX)	
	fw.write('created by ODM, '+curDateStr()+'\n')
}

function printCVS (fw){
	fw.write(relModel+';;;\n')
	fw.write('entityName;attrName;tableName;columnName\n')
	tables = relModel.getTableSet().toArray();
	for (itpc=0;itpc<tables.length;itpc++){
		printCols(fw,tables[itpc])
	}
}

function print1Mapping (){
	logicalModel = model.getDesign().getLogicalDesign();
	entitySet = logicalModel.getEntitySet()
	relationSet = logicalModel.getRelationSet()
	inheritanceSet = logicalModel.getInheritanceRelationSet()
	relModel = chooseModel(relModel);
	if (relModel == null) return;
	// lies alle Mappings des gewählten Modells
	getAllMappings([relModel])

	fileName=chooseFile(exportDirec,relModel+'.csv')
     if (fileName == null) return
     fw = createFile(fileName)
	printCVS (fw)
     fw.close();    
	message("Mapping file "+fileName+" for model "+relModel+" created.");
}

function printAllMapping (nurX){
	fileName=chooseFile(exportDirec,'AllMapping' + (nurX ? 'X' : '') +'.csv')
     if (fileName == null) return
     fw = createFile(fileName)
     printMatrix(fw,nurX)
     fw.close();    
	message("Mapping file "+fileName+" created.");
}
function printXMapping (){
     printAllMapping(true)
}
function printNameMapping (){
     printAllMapping(false)
}

			//scripts to handle translation of model
				var CODEVERSION = '1.5'
				var gLogNote = "LOG";
				var gParams={}
			// Translation
				var gTranslInforegexp =/TRANSLATION\{([^}]*)\}/;
				var translation = false
